{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I'm working on producing squares since that's my specialty. I'm thinking we could trade a square for a circle if you're open to it. How does that sound?"
    }
  },
  "rationale": "I have a specialty shape (square) that others need (circle), so initiating a trade offers mutual benefit and aligns with my goal of fulfilling my order efficiently."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm curious — do you have any squares you can share? I need one for my order and I'm thinking we could trade if you're open to it."
    }
  },
  "rationale": "I need a square to fulfill my order, and since B has the specialty square, they're the best source. Starting a direct conversation to explore a trade is a low-risk, high-reward move."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "C"
      ],
      "content": "Hey, I'm working on getting a triangle for my order. Since you're the one who makes triangles, I was wondering if you'd be open to trading one for a bit of money? Maybe $20 or so?"
    }
  },
  "rationale": "I need a triangle to fulfill my order, and C has the specialty shape. Starting a direct conversation to propose a trade is a low-risk, practical first step."
}

